'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const ids=['north','east','south','west'],names=[['North','北'],['East','東'],['South','南'],['West','西']],arrows=['↑','→','↓','←'];
let variant=OrionProgress.variant('shadows'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,direction=0,height=0,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false;
function target(v=variant,s=stage){return{direction:(v+s)%4,short:(Math.floor(v/4)+s)%2};}
function shadow(){return{direction:(direction+2)%4,short:height};}
function description(d){return `${arrows[d.direction]} ${t(...names[d.direction])} · ${d.short?t('Short','短'):t('Long','長')}`;}
function resetTrial(){const goal=target();direction=goal.direction;height=1-goal.short;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('shadows')){variant=v;stage=0;resetTrial();}
function moveLight(n){if(solved||!Number.isInteger(n)||n<0||n>3)return;direction=n;state='changed';render();}
function raiseLight(n){if(solved||!Number.isInteger(n)||n<0||n>1)return;height=n;state='changed';render();}
function matches(){const a=shadow(),b=target();return a.direction===b.direction&&a.short===b.short;}
function check(){if(solved)return;history.unshift(shadow());if(!matches()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('sunshadow');render();if(stage<2)$('next').focus();}
function hints(){const g=target();return[t('Move the light to another side. Which way does the shadow point? Then try raising the light.','把光移到另一邊。影子指向哪裡？再試試把光升高。'),t('The pillar blocks light. The shadow points away from the light. Higher light makes a shorter shadow.','石柱擋住光。影子指向背光的一方；光越高，影子越短。'),t(`For this seal, put the light in the ${names[(g.direction+2)%4][0]} and set it ${g.short?'High':'Low'}.`,`這道封印：把光放在${names[(g.direction+2)%4][1]}方，並調至${g.short?'高':'低'}。`)];}
function render(){const g=target(),a=shadow(),complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Sunstone Courtyard · Orion','日影石庭 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Shadow seals opened · ${count} / 3`,`已打開 ${count} / 3 道影子封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);$('mission').textContent=t('Make the pillar’s shadow fit the dashed outline. Choose a light direction and height.','讓石柱的影子配對虛線輪廓。選擇光的方向和高度。');ids.forEach((id,i)=>{$(id).disabled=solved;$(id).setAttribute('aria-pressed',String(i===direction));$(id).setAttribute('aria-label',t(`Place the light in the ${names[i][0]}`,`把光放在${names[i][1]}方`));});$('height').value=height;$('height').disabled=solved;$('heightLabel').textContent=t('Light height: ','光源高度：')+(height?t('High','高'):t('Low','低'));$('height').setAttribute('aria-valuetext',height?t('High','高'):t('Low','低'));
$('goal').innerHTML=t('Dashed goal','虛線目標')+`<strong>${description(g)}</strong>`;$('reading').innerHTML=t('Your solid shadow','你的實色影子')+`<strong>${description(a)}</strong>`;
const length=d=>d.short?32:96,xy=(d,l)=>[[220,130-l],[220+l,130],[220,130+l],[220-l,130]][d],sun=xy(direction,108),tip=xy(a.direction,length(a));
$('diagram').setAttribute('aria-label',t(`Top view. Light: ${names[direction][0]}, ${height?'high':'low'}. Shadow: ${description(a)}. Goal: ${description(g)}.`,`俯視圖。光：${names[direction][1]}方，${height?'高':'低'}。影子：${description(a)}。目標：${description(g)}。`));
$('diagram').innerHTML=`<svg viewBox="0 0 440 260" aria-hidden="true"><defs><radialGradient id="stone"><stop stop-color="#bca477"/><stop offset="1" stop-color="#66583b"/></radialGradient></defs><circle cx="220" cy="130" r="110" fill="url(#stone)" stroke="#c4a361" stroke-width="3"/><circle cx="220" cy="130" r="72" fill="none" stroke="#d5bd8955"/><path d="M220 20V240M110 130H330" stroke="#dec79966"/><path class="shadow-path" d="M220 130L${tip.join(' ')}" stroke="#17222d" stroke-width="18" stroke-linecap="round"/><rect x="208" y="${130-length(g)}" width="24" height="${length(g)}" rx="6" transform="rotate(${g.direction*90} 220 130)" fill="none" stroke="#fff2b7" stroke-width="3" stroke-dasharray="5 4"/><circle cx="220" cy="130" r="12" fill="#edcd8a" stroke="#473e2b" stroke-width="3"/><circle cx="${sun[0]}" cy="${sun[1]}" r="12" fill="#ffe485" stroke="#fff5cb" stroke-width="2"/><text x="220" y="13" text-anchor="middle" fill="#edf0e7" font-size="14">${t('N','北')}</text><text x="353" y="135" fill="#edf0e7" font-size="14">${t('E','東')}</text><text x="220" y="258" text-anchor="middle" fill="#edf0e7" font-size="14">${t('S','南')}</text><text x="74" y="135" fill="#edf0e7" font-size="14">${t('W','西')}</text><text x="10" y="25" fill="#ffe485" font-size="13">☀ ${t('Light','光')}</text><text x="10" y="245" fill="#edf0e7" font-size="13">${t('Top view · model','俯視圖 · 模型')}</text></svg>`;
const msg={ready:t('Try moving the light. The shadow will respond immediately.','試試移動光，影子會立即改變。'),changed:matches()?t('The direction and length match! Open the seal.','方向和長短都配對了！打開封印吧。'):t('Compare your shadow’s direction AND length with the dashed goal.','比較影子和虛線目標的方向，以及長短。'),wrong:t('Not the same shadow yet. Change the light direction or height and try again.','影子還未相同。調整光的方向或高度，再試一次。'),success:t('Shadow matched! A sunstone seal opens.','影子配對了！一道日影封印打開。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.slice(0,4).map(d=>`<li>${description(d)} ${d.direction===g.direction&&d.short===g.short?'✓':'↻'}</li>`).join('')||`<li>${t('Your checked shadows appear here.','檢查過的影子會記錄在這裡。')}</li>`;for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('sunshadow')?t('Sunshadow Sigil saved in your collection.','日影符印已存入收藏。'):'';
}
ids.forEach((id,i)=>$(id).onclick=()=>moveLight(i));$('height').oninput=e=>raiseLight(Number(e.target.value));$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('north').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('shadows',variant);observedVariant=OrionProgress.variant('shadows');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('sunshadow');render();};
function syncProgress(){const v=OrionProgress.variant('shadows'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('sunshadow')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
